class Solution {
public:
    int magicalString(int n) {
        if (n <= 0) return 0;
        if (n <= 3) return 1;
        string s = "122";
        int i = 2;
        int ones = 1;
        while ((int)s.size() < n) {
            char c = (s.back() == '1') ? '2' : '1';
            int count = s[i] - '0';
            for (int j = 0; j < count && (int)s.size() < n; j++) {
                s.push_back(c);
                if (c == '1') ones++;
            }
            i++;
        }
        return ones;
    }
};
